public static boolean startsWith(String str, String prefix, boolean ignoreCase) {
    if (str == null || prefix == null) {
        return str == null && prefix == null;
    }
    int byteCount = countBytes(str);
    int prefixByteCount = countBytes(prefix);
    if (byteCount < prefixByteCount + 1) {
        return false;
    }
    int sourceCount = 0;
    while (sourceCount < prefixByteCount && str.charAt(sourceCount) == prefix.charAt(sourceCount)) {
        sourceCount++;
    }
    return sourceCount == prefixByteCount && (ignoreCase || str.charAt(sourceCount) == prefix.charAt(sourceCount));
}

