private void putAbstractTypes(final int start, final int end) {
    final int[] types = currentFrame.getLocalTypes();
    for (int i = start; i < end; i++) {
        final int t = types[i];
        switch (t) {
            case AbstractTag.Top:
            case AbstractTag.Integer:
            case AbstractTag.Float:
            case AbstractTag.Long:
            case AbstractTag.Double:
            case AbstractTag.Null:
            case AbstractTag.UninitializedThis:
            case AbstractTag.Object:
                stackMapTableEntries.put((0 << 4) | t);
                break;
            case AbstractTag.Uninitialized:
                stackMapTableEntries.put((1 << 4) | ((currentFrame.getStackSlot(i) << 2) | AbstractTag.Uninitialized));
                break;
            case AbstractTag.Initialized:
                stackMapTableEntries.put((1 << 4) | ((currentFrame.getStackSlot(i) << 2) | AbstractTag.Object));
                break;
            default:
                throw new Exception("Invalid abstract tag " + t);
        }
    }
}

