public final String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    // Get the start and end indexes of the CONSTANT_Utf8 entry in the class file buffer
    int startIndex = classFileBuffer[constantPoolEntryIndex];
    int endIndex = classFileBuffer[constantPoolEntryIndex + 1];

    // Append the string to the char buffer
    for (int i = startIndex; i < endIndex; i++) {
        charBuffer[i] = (char) classFileBuffer[i];
    }

    // Return the String
    return new String(charBuffer, startIndex, endIndex - startIndex);
