    // Split the pattern parts into an array
    String[] patternParts = pattern.split("/");
    // Split the URI parts into an array
    String[] uriParts = uri.split("/");
    // Check if the number of pattern parts is greater than the number of URI parts
    if (patternParts.length > uriParts.length) {
        // No match if the number of pattern parts is greater than the number of URI parts
        return null;
    }
    // Initialize the index variable
    int index = 0;
    // Iterate over the pattern parts
    for (String patternPart : patternParts) {
        // Get the URI part for the current pattern part
        String uriPart = uriParts[index];
        // Check if the pattern part is a wildcard
        if (patternPart.equals("*")) {
            // If the pattern part is a wildcard, return a match result
            return new MatchResult(uriParts, index);
        }
        // Check if the pattern part is a regex
        if (patternPart.startsWith("{") && patternPart.endsWith("}")) {
            // If the pattern part is a regex, use the "matches" method to match against the current URI part
            if (!uriPart.matches(patternPart.substring(1, patternPart.length() - 1))) {
                // If the pattern doesn't match the current URI part, return null
                return null;
