        } else {
            // If the pattern part is a fixed string, use the "equals" method to match against the current URI part
            if (!uriPart.equals(patternPart)) {
                // If the pattern doesn't match the current URI part, return null
                return null;
            }
        }
        // Increment the index variable
        index++;
    }
    // Return a match result if all pattern parts match the corresponding URI parts
    return new MatchResult(uriParts, index);
}

