if (path.startsWith(separator)) {
return relativePath;
}

// If the given relative path is already an absolute path, return the path
if (relativePath.startsWith(separator)) {
return path;
}

// Join the path and relative path using the separator
String joinedPath = path + separator + relativePath;

// Remove any duplicate separators
return joinedPath.replaceAll("[" + separator + "]{2,}", separator);
}

