public String format(LoggingEvent event) {
    StringBuilder builder = new StringBuilder();

    // Parse the conversion pattern to determine the format of the output string
    String conversionPattern = getConversionPattern();
    String[] tokens = conversionPattern.split("");

    // Iterate over the tokens in the conversion pattern
    for (String token : tokens) {
        // If the token is a literal string, append it to the output string
        if (token.startsWith("'")) {
            builder.append(token.substring(1));
        }
        // If the token is a conversion specifier, use it to format the logging event
        else if (token.startsWith("%")) {
            // Extract the conversion character and the format modifiers from the token
            char conversionChar = token.charAt(0);
            String formatModifiers = token.substring(1);

            // Format the logging event according to the conversion character and format modifiers
            switch (conversionChar) {
                case 'd': // Date
                    String dateFormat = formatModifiers.substring(1, formatModifiers.indexOf('"'));
                    SimpleDateFormat sdf = new SimpleDateFormat(dateFormat);
                    builder.append(sdf.format(event.getTimeStamp()));
                    break;
                case 'l': // Level
                    builder.append(event.getLevel().toString());
                    break;
                case 'L': // Logger
                    builder.append(event.getLogger().getName());
                    break;
                case 'm': // Message
                    builder.append(event.getMessage());
                    break;
                case 'p': // Priority
                    builder.append(event.getPriority());
                    break;
                case 't': // Thread
                    builder.append(event.getThreadName());
                    break;
                default:
                    builder.append(token); // Unknown conversion character, just append it
                    break;
            }
        }
        else {
            builder.append(token); // Literal string, just append it
        }
    }

    return builder.toString();
}

