public String findAndSubst(String key, Properties props) {
  String value = props.getProperty(key);
  if (value == null) {
    return null;
  }
  String result = Matcher.quoteReplacement(value);
  Matcher matcher = Pattern.compile("\\$\\{[^}]+\\}").matcher(value);
  while (matcher.find()) {
    String placeholder = matcher.group();
    String placeholderName = placeholder.substring(2, placeholder.length() - 1);
    String placeholderValue = props.getProperty(placeholderName);
    if (placeholderValue == null) {
      return null;
    }
    result = result.replace(placeholder, placeholderValue);
  }
  return result;
}

