public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb){
  int len = str.length();
  int strPos = 0;
  int bufferPos = lb.size();
  int bytesAdded = 0;
  while (strPos < len) {
    char c = str.charAt(strPos);
    strPos++;
    if (c > 0 && c <= 0x007F) {
      bytesAdded++;
    } else if (c > 0x07FF) {
      bytesAdded += 3;
    } else {
      bytesAdded++;
    }
    if (bytesAdded > session.getMaxCharsPerBuffer()) {
      // split the string into 2 parts and create a new buffer
      bytesAdded = bytesAdded - lb.size(bufferPos);
      session.writeToBuffer(new String(str.subSequence(strPos - 1, str.length())), bytesAdded, lb);
      return lb;
    }
  }
  // add the remaining chars to the buffer
  lb.addString(str, bufferPos, session.getMaxCharsPerBuffer() - bytesAdded);
  return lb;
}

