public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    // Write the number of elements in the buffer
    out.writeInt(node.size());

    // Write each element in the buffer
    for (Map.Entry<Object, Object> entry : node.getEntries()) {
        // Write the key and value of the entry
        out.writeObject(entry.getKey());
        out.writeObject(entry.getValue());
    }

    // Return the total size of the buffer
    return node.size() * (Integer.BYTES * 2) + out.getPos();
}

