int readTag() throws IOException {
  while (true) {
    int tag = input.readByte();
    if (tag == -1) {
      return 0;
    }
    if (tag == 0) {
      continue;
    }
    if ((tag & 0x80) == 0) {
      return tag;
    }
    int nextByte = input.readByte();
    if (nextByte == -1) {
      throw new IOException("Unexpected EOF after tag continuation byte");
    }
    return (tag & 0x7F) | ((nextByte & 0x7F) << 7);
  }
}

